import wave, numpy as np
w=wave.open('work/pt.wav'); 
d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').astype(float)/32768
L=d[0::2]; sr=44100; row=6*2.5/125
def dom(seg):
    seg=seg-np.mean(seg)
    sp=np.abs(np.fft.rfft(seg*np.hanning(len(seg))))
    fr=np.fft.rfftfreq(len(seg),1/sr)
    i=np.argmax(sp)
    # parabolic
    if 0<i<len(sp)-1:
        a,b,c=sp[i-1],sp[i],sp[i+1]
        return fr[i]+0.5*(a-c)/max(a-2*b+c,1e-9)*(fr[1]-fr[0])
    return fr[i]
for n,r in [("C-4",0),("C-5",8),("A-4",16),("D-3",24),("E-2",32)]:
    s=int(r*row*sr)+200; e=s+int(0.5*sr)
    print(n, round(dom(L[s:e]),2))
EOF"}

